// Implementation cần id — constrain. Đừng generic "phòng hờ".
function upsertById<T extends { id: string }>(rows: T[], row: T): T[] {
  const i = rows.findIndex((r) => r.id === row.id)
  if (i === -1) return [...rows, row]
  return rows.with(i, row)
}

